const escape = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
export const bootstrapClassPattern = new RegExp(
  `^(?:${prefixes.map(escape).join('|')})(?:-[\\w.:%/-]+)?$|^fa-[\\w-]+$`,
);
// Spacing / gutter utilities have a closed value set: m-3, px-md-2, mt-n1, g-0, gap-2, gy-lg-4.
const spacingPattern =
  /^(?:[mp][xytbse]?|g[xy]?|gap(?:-[xy])?)(?:-(?:sm|md|lg|xl|xxl))?-(?:auto|n?[0-5])$/;
export const isAllowedThemeClass = (token) =>
  spacingPattern.test(token) || bootstrapClassPattern.test(token);
